from typing import List, Literal
from pydantic import BaseModel, Field
DocType = Literal["design_doc", "test_result", "deployment_plan"]
class Tools:
    class Valves(BaseModel):
        BASE_URL: str = ""
    class UserValves(BaseModel):
        PAT: str = Field(default="", repr=False)
    def __init__(self):
        self.valves = self.Valves()
    def list_documents(self, doc_types: List[DocType], __user__: dict) -> dict:
        if not __user__["valves"].PAT:
            raise ValueError("fixture credential missing")
        base = self.valves.BASE_URL.rstrip("/")
        documents = [
            {"id": "101", "title": "EMS 셋업 설계서", "document_type": "design_doc", "url": base + "/pages/101"},
            {"id": "102", "title": "EMS 통합 테스트 결과", "document_type": "test_result", "url": base + "/pages/102"}
        ]
        return {"documents": [row for row in documents if row["document_type"] in doc_types]}
